mapper.select:
/* CompanyProvisionMapper.selectCmpnyExists */
SELECT COUNT(1)
FROM TB_CMPNY A
WHERE A.CMPNY_CD = #{cmpnyCd}

/* CompanyProvisionMapper.selectUserIdExists */
SELECT COUNT(1)
FROM TB_USER A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.USER_ID  = #{userId}

/* CompanyProvisionMapper.selectPhoneNumberExists */
SELECT COUNT(1)
FROM TB_USER A
WHERE A.MBL_NO_HMAC = #{phoneHmac}   
  AND A.USE_YN = 'Y'

mapper.insert:
/* CompanyProvisionMapper.insertCmpny */
INSERT INTO TB_CMPNY (
    CMPNY_CD
    , CMPNY_NM
    , BSNS_LCN_NO
    , USE_YN
    , CONTRACT_YN
    , CONTRACT_END_DATE
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
    #{cmpnyCd}
    , #{cmpnyNm}
    , #{bsnsLcnNo}
    , #{useYn}
    , #{contractYn}
    , #{contractEndDate}
    , #{insertNo}
    , NOW()
)

mapper.select:
/* CompanyProvisionMapper.selectNextUserCd */
SELECT CONCAT(DATE_FORMAT(NOW(), '%Y%m'), FNC_CMM_SEQ_NEXTVAL(#{cmpnyCd}, 'USER_CD'))
FROM DUAL

mapper.insert:
/* CompanyProvisionMapper.insertUser */
INSERT INTO TB_USER (
    CMPNY_CD
    , USER_CD
    , USER_ID
    , USER_NM
    , USER_PW
    , SITE_CD
    , NODE_CD
    , AUTH_CD
    , MBL_NO_ENC
    , MBL_NO_HMAC
    , MBL_NO_LAST4
    , USE_YN
    , ACCOUNT_STATUS
    , PWD_LOCK_YN
    , PWD_FAIL_CNT
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
)
VALUES (
    #{cmpnyCd}
    , #{userCd}
    , #{userId}
    , #{userNm}
    , #{userPw}
    , #{siteCd}
    , #{nodeCd}
    , #{authCd}
    , #{mblNoEnc}
    , #{mblNoHmac}
    , #{mblNoLast4}
    , 'Y'
    , #{accountStatus}
    , 'N'
    , 0
    , #{insertNo}
    , NOW()
    , #{insertNo}
    , NOW()
)

/* CompanyProvisionMapper.insertSite */
INSERT INTO TB_SITE (
    CMPNY_CD
    , SITE_CD
    , SITE_NO
    , SITE_NM
    , STR_DATE
    , USE_YN
    , SITE_ADMIN_CD
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
)
VALUES (
    #{cmpnyCd}
    , #{siteCd}
    , #{siteNo}
    , #{siteNm}
    , #{strDate}
    , 'Y'
    , #{siteAdminCd}
    , #{insertNo}
    , NOW()
    , #{insertNo}
    , NOW()
)

/* CompanyProvisionMapper.insertSiteNode */
INSERT INTO TB_SITE_NODE (
    CMPNY_CD
    , SITE_CD
    , NODE_CD
    , NODE_NM
    , NODE_TYPE
    , SELF_ATTD_APPRV_YN
    , MAIN_ADMIN_CD
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
)
VALUES (
    #{cmpnyCd}
    , #{siteCd}
    , #{nodeCd}
    , #{nodeNm}
    , #{nodeType}

    , CASE WHEN #{nodeCd} = 'n1' THEN 'Y' ELSE 'N' END
    , #{mainAdminCd}
    , #{insertNo}
    , NOW()
    , #{insertNo}
    , NOW()
)

/* CompanyProvisionMapper.insertUserSiteAuth */
INSERT INTO TB_USER_SITE_AUTH (
    CMPNY_CD
    , USER_CD
    , SITE_CD
    , USE_YN
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
)
VALUES (
    #{cmpnyCd}
    , #{userCd}
    , #{siteCd}
    , 'Y'
    , #{gvUserCd}
    , NOW()
    , #{gvUserCd}
    , NOW()
)

/* CompanyProvisionMapper.copyBaimValMFromTemplate */
INSERT INTO tb_baim_val_m (
    CMPNY_CD, BAIM_VAL_CD, BAIM_VAL_NM, USE_YN, INSERT_NO, INSERT_DATE, UPDATE_NO, UPDATE_DATE
)
SELECT
    #{newCmpnyCd}, BAIM_VAL_CD, BAIM_VAL_NM, USE_YN,
    #{gvUserCd}, NOW(), #{gvUserCd}, NOW()
FROM tb_baim_val_m
WHERE CMPNY_CD = #{srcCmpnyCd}
  AND USE_YN = 'Y'

/* CompanyProvisionMapper.insertWorktype */
INSERT INTO TB_SCH_MGMT (
    CMPNY_CD, SITE_CD, SCH_CD, SCH_NO, SCH_TYPE, APPLY_DATE, FST_SCH_STR_TIME, FST_SCH_END_TIME,
    USE_YN, INSERT_NO, INSERT_DATE, UPDATE_NO, UPDATE_DATE
)
VALUES (
    #{cmpnyCd}, #{siteCd}, #{schCd}, #{schNo}, #{schType}, #{applyDate}, #{fstSchStrTime}, #{fstSchEndTime},
    'Y', #{insertNo}, NOW(), #{insertNo}, NOW()
)
